\begin{lemma}
Let $p$ be an odd prime. Then
\[
\sum_{k=1}^{(p-1)/2}\frac{4^k}{k\binom{2k}{k}}
\equiv 2\left((-1)^{(p-1)/2}-1\right)\pmod p.
\]
\end{lemma}

